#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
SV="$GSZ/server.js"; AD="$GSZ/routes/admin.js"; CT="$GSZ/views/admin/content.ejs"; SB="$GSZ/views/partials/store_bottom.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step189: admin social links (auto platform icons) + WhatsApp Channel button"
for F in "$SV" "$AD" "$CT" "$SB"; do cp "$F" "$F.bak-step189-$TS"; done
echo "    backups: *.bak-step189-$TS"
restore(){ echo "!! restoring"; for F in "$SV" "$AD" "$CT" "$SB"; do cp "$F.bak-step189-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
P=$(mktemp /tmp/p189.XXXXXX.js); echo "" | base64 -d > "$P"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$P" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$SV" && echo "    server.js ok"
NODE_PATH="$GSZ/node_modules" node --check "$AD" && echo "    admin.js ok"
for V in "$CT" "$SB"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: '+'$V'.replace('$GSZ/',''))"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
rm -f "$P"; trap - ERR
echo ""
echo "==> step189 OK  Admin > Content now has 'Social links' (one URL per line, auto platform icons in the footer) + a 'WhatsApp Channel link' that shows a 'Join our WhatsApp Channel' button. Add your links there and save."
